 private void applyReviewBucket(){unfinishedReviewButton.setSelected(!completedReviews);completedReviewButton.setSelected(completedReviews);requestReviewCol.setVisible(completedReviews);reviewFiltered=reviewRequests.stream().filter(r->completedReviews?r.getStatus()!=StudentChangeStatus.PENDING:r.getStatus()==StudentChangeStatus.PENDING).toList();reviewPage=1;renderReviewPage();}
 private void renderReviewPage(){int pages=Math.max(1,(reviewFiltered.size()+19)/20);reviewPage=Math.max(1,Math.min(reviewPage,pages));int from=Math.min((reviewPage-1)*20,reviewFiltered.size());requestTable.setItems(FXCollections.observableArrayList(reviewFiltered.subList(from,Math.min(from+20,reviewFiltered.size()))));reviewPageSummary.setText("共"+reviewFiltered.size()+"条  第"+reviewPage+" / "+pages+"页");}
