 private void closeTeacherReview(){reviewEpoch++;service.reviewLease.close();if(reviewListContent!=null){reviewTab.setContent(reviewListContent);reviewListContent=null;}approveReviewButton=null;rejectReviewButton=null;reviewReason=null;}
 private void reviewLoadError(VBox page,String message,TeacherChangeRequest row){statusLabel.setText(message);Button retry=new Button("重新加载");retry.setOnAction(e->openTeacherReview(row));page.getChildren().set(1,new VBox(12,new Label("加载失败："+message),retry));service.reviewLease.close();}
 private void openTeacherReview(TeacherChangeRequest row){if(disposed||service.reviewLease.busy())return;closeTeacherReview();long expected=++reviewEpoch;reviewListContent=reviewTab.getContent();VBox page=new VBox(14);page.getStyleClass().add("student-page");page.setPadding(new javafx.geometry.Insets(18,24,20,24));Button back=new Button("← 返回审核总览");back.getStyleClass().add("btn-secondary");back.setOnAction(e->closeTeacherReview());Label heading=new Label("申请修改详情");heading.getStyleClass().add("student-section-title");page.getChildren().addAll(new HBox(14,back,heading),new Label("正在加载完整信息…"));reviewTab.setContent(page);
 Runnable load=()->service.reviewQuery(row.getRequestId(),response->{if(disposed||expected!=reviewEpoch)return;if(!ok(response)){reviewLoadError(page,response.getMessage(),row);return;}TeacherChangeRequest request=data(response,"request",TeacherChangeRequest.class);if(request==null){reviewLoadError(page,"审核申请不存在",row);return;}service.query(request.getTeacherId(),message->{if(disposed||expected!=reviewEpoch)return;if(!ok(message)){reviewLoadError(page,message.getMessage(),row);return;}TeacherOverviewVO profile=data(message,"overview",TeacherOverviewVO.class);if(profile==null||profile.getTeacher()==null){reviewLoadError(page,"教师档案不存在",row);return;}renderTeacherReview(page,request,profile,expected);});});
 if(row.getStatus()==StudentChangeStatus.PENDING)service.reviewLease.acquire("TEACHER_CHANGE_REQUEST",String.valueOf(row.getRequestId()),load,error->{if(!disposed&&expected==reviewEpoch)reviewLoadError(page,error,row);});else load.run();
 }
