 private void renderTeacherReview(VBox page,TeacherChangeRequest request,TeacherOverviewVO profile,long expected){VBox records=new VBox(14);records.setMinWidth(850);HBox.setHgrow(records,Priority.ALWAYS);Map<String,TeacherChangeItem> changes=new HashMap<>();for(TeacherChangeItem i:request.getItems())changes.put(i.getFieldName(),i);List<List<String>> groups=List.of(BASE,JOB,CONTACT);String[] names={"个人基本信息","任职信息","联系信息"};for(int k=0;k<groups.size();k++){VBox section=reviewSection(names[k]);GridPane grid=new GridPane();grid.setHgap(12);grid.setVgap(9);prepareSixColumns(grid);List<String> fields=groups.get(k);for(int i=0;i<fields.size();i++){String field=fields.get(i);Label key=new Label(title(field));key.getStyleClass().add("student-field-key");key.setMaxWidth(Double.MAX_VALUE);TeacherChangeItem change=changes.get(field);javafx.scene.Node value;if(change==null){Label label=new Label(show(read(profile.getTeacher(),field)));label.setWrapText(true);value=label;}else{Label old=new Label("原值："+show(change.getOldValue())),updated=new Label("申请值："+show(change.getNewValue()));old.setWrapText(true);updated.setWrapText(true);VBox diff=new VBox(4,old,updated);diff.setStyle("-fx-background-color: #fff5d6; -fx-padding: 8; -fx-background-radius: 5;");value=diff;}grid.add(key,(i%3)*2,i/3);grid.add(value,(i%3)*2+1,i/3);}section.getChildren().add(grid);records.getChildren().add(section);}
 VBox work=reviewSection("工作经历"),workCards=new VBox(10),family=reviewSection("主要社会关系"),familyCards=new VBox(10);renderExperiences(profile.getWorkExperiences(),workCards,false);renderDetailFamily(familyCards,profile.getFamilyMembers());work.getChildren().add(workCards);family.getChildren().add(familyCards);records.getChildren().addAll(work,family);
 VBox actions=reviewSection("审核处理");actions.setMinWidth(280);actions.setPrefWidth(320);TextArea reason=new TextArea(request.getReviewRemark());reason.setPromptText("填写审核理由");reason.setWrapText(true);reason.setPrefRowCount(6);Button approve=new Button("通过"),reject=new Button("不通过");approve.getStyleClass().add("btn-primary");reject.getStyleClass().add("btn-secondary");boolean pending=request.getStatus()==StudentChangeStatus.PENDING&&service.reviewLease.valid();approve.setDisable(!pending);reject.setDisable(!pending);reason.setEditable(pending);approveReviewButton=approve;rejectReviewButton=reject;reviewReason=reason;
 actions.getChildren().addAll(new Label("状态："+reviewStatusText(request.getStatus())),new Label("提交时间："+show(request.getSubmitTime())),new Label("处理时间："+show(request.getReviewTime())),new HBox(8,approve,reject),new Label("理由"),reason);
 java.util.concurrent.atomic.AtomicBoolean submitting=new java.util.concurrent.atomic.AtomicBoolean();java.util.function.Consumer<StudentChangeStatus> decide=result->{if(disposed||expected!=reviewEpoch||!service.reviewLease.valid()||!submitting.compareAndSet(false,true))return;approve.setDisable(true);reject.setDisable(true);TeacherReviewVO v=new TeacherReviewVO();v.setRequestId(request.getRequestId());v.setReviewResult(result);v.setReviewRemark(reason.getText()==null?"":reason.getText().trim());service.review(v,response->{submitting.set(false);if(disposed||expected!=reviewEpoch)return;statusLabel.setText(response.getMessage());if(ok(response)){closeTeacherReview();completedReviews=true;loadAdmin();}else{boolean enabled=service.reviewLease.valid();approve.setDisable(!enabled);reject.setDisable(!enabled);}});};approve.setOnAction(e->decide.accept(StudentChangeStatus.APPROVED));reject.setOnAction(e->decide.accept(StudentChangeStatus.REJECTED));HBox body=new HBox(18,records,actions);body.setAlignment(Pos.TOP_LEFT);ScrollPane scroll=new ScrollPane(body);scroll.setFitToWidth(true);scroll.getStyleClass().add("student-scroll");VBox.setVgrow(scroll,Priority.ALWAYS);page.getChildren().set(1,scroll);
 }

 private Teacher displayedTeacher(){if(overview==null||overview.getTeacher()==null)return null;Teacher copy=gson.fromJson(gson.toJson(overview.getTeacher()),Teacher.class);TeacherChangeRequest pending=overview.getPendingRequest();if(!isAdmin()&&pending!=null&&pending.getStatus()==StudentChangeStatus.PENDING)for(TeacherChangeItem item:pending.getItems())if(EDITABLE.contains(item.getFieldName()))write(copy,item.getFieldName(),item.getNewValue()==null?"":item.getNewValue());return copy;}

