 private void fill(GridPane g,Teacher t,List<String> fields){prepareSixColumns(g);g.getChildren().clear();for(int i=0;i<fields.size();i++){String f=fields.get(i);Label k=new Label(title(f)),v=new Label(show(read(t,f)));k.getStyleClass().add("student-field-key");k.setAlignment(Pos.CENTER_LEFT);k.setMinWidth(136);k.setPrefWidth(136);k.setMaxWidth(136);k.setTooltip(new Tooltip(k.getText()));v.getStyleClass().add("student-field-value");v.setAlignment(Pos.CENTER_LEFT);v.setWrapText(true);v.setMinWidth(0);v.setMaxWidth(Double.MAX_VALUE);v.setTooltip(new Tooltip(v.getText()));int row=i/3,pair=i%3;g.add(k,pair*2,row);g.add(v,pair*2+1,row);}}
 private void beginGlobalEdit(){
    if(disposed||editing||service.recordInFlight||service.editLease.busy()||overview==null||overview.getTeacher()==null)return;
    if(overview.getPendingRequest()!=null){String message=isAdmin()?"该教师档案存在待审核申请，请先完成审核后再编辑。":"当前已有修改申请正在等待审核，审核完成后才能再次编辑。";AlertUtil.showWarning("暂时无法编辑",message);return;}
    String id=overview.getTeacher().getTeacherId();long expected=++detailEpoch;
    service.editLease.acquire("TEACHER",id,()->{
        java.util.function.Consumer<Message> loaded=m->{
            if(disposed||expected!=detailEpoch)return;
            if(!ok(m)||!service.editLease.valid()){service.editLease.close();statusLabel.setText("编辑数据加载失败，请重新进入");return;}
            overview=data(m,"overview",TeacherOverviewVO.class);
            if(overview==null||overview.getTeacher()==null||!id.equals(overview.getTeacher().getTeacherId())||overview.getPendingRequest()!=null){service.editLease.close();statusLabel.setText("档案状态已变化，请刷新");return;}
            openGlobalEditor();
        };
        if(isAdmin())service.query(id,loaded);else service.overview(loaded);
    },error->{if(!disposed){statusLabel.setText(error);AlertUtil.showWarning("暂时无法编辑",error);}});
 }
 private void openGlobalEditor(){editableControls.clear();editing=true;saving=false;fillEditable(baseGrid,BASE);fillEditable(jobGrid,JOB);fillEditable(contactGrid,CONTACT);Button cancel=new Button("取消");cancel.getStyleClass().add("btn-secondary");cancel.setOnAction(e->cancelEdit());Button submit=new Button(isAdmin()?"保存修改":"提交修改申请");saveButton=submit;submit.getStyleClass().add("btn-primary");submit.setOnAction(e->submitEdit());HBox actions=new HBox(8,cancel,submit);actions.setAlignment(Pos.CENTER_RIGHT);contactGrid.add(actions,0,(CONTACT.size()+2)/3,6,1);statusLabel.setText(isAdmin()?"全部信息已进入编辑状态，保存后直接生效":"全部信息已进入编辑状态，提交后等待审核");}
 private void fillEditable(GridPane grid,List<String> fields){prepareSixColumns(grid);grid.getChildren().clear();Teacher teacher=overview.getTeacher();for(int i=0;i<fields.size();i++){String field=fields.get(i);Label key=new Label(title(field));key.getStyleClass().add("student-field-key");if(REQUIRED.contains(field)){Label star=new Label("*");star.setStyle("-fx-text-fill: #dc2626; -fx-font-weight: bold;");key.setGraphic(star);key.setContentDisplay(ContentDisplay.RIGHT);}key.setAlignment(Pos.CENTER_LEFT);key.setMinWidth(136);key.setPrefWidth(136);key.setMaxWidth(136);Control value=createEditor(field,showInput(read(teacher,field)));value.setUserData(field);value.setMinWidth(0);value.setMaxWidth(Double.MAX_VALUE);boolean allowed=isAdmin()||EDITABLE.contains(field);value.setDisable(!allowed);if(allowed)editableControls.add(value);int row=i/3,pair=i%3;grid.add(key,pair*2,row);grid.add(value,pair*2+1,row);}}
 private Control createEditor(String field,String initial){Control control;if(Set.of("idIssueDate","birthDate","partyJoinDate","employmentStartDate").contains(field)){DatePicker picker=new DatePicker();if(!initial.isBlank())try{picker.setValue(java.time.LocalDate.parse(initial));}catch(Exception ignored){}control=picker;}else if("idType".equals(field)){ComboBox<String> combo=new ComboBox<>(FXCollections.observableArrayList("居民身份证","港澳台居民居住证","护照","其他"));combo.setValue(initial);control=combo;}else if("householdType".equals(field)){ComboBox<String> combo=new ComboBox<>(FXCollections.observableArrayList("城镇户口","农村居民户口","集体户口","其他"));combo.setValue(initial);control=combo;}else if(Set.of("partyMember","employed").contains(field)){ComboBox<String> combo=new ComboBox<>(FXCollections.observableArrayList("是","否"));combo.setValue(Set.of("true","1","是","在职").contains(initial)?"是":"否");control=combo;}else control=new TextField(initial);control.getStyleClass().add("form-control");return control;}
 private String controlValue(Control control){if(control instanceof TextInputControl text)return text.getText().trim();if(control instanceof DatePicker date)return date.getValue()==null?"":date.getValue().toString();if(control instanceof ComboBox<?> combo)return combo.getValue()==null?"":String.valueOf(combo.getValue()).trim();return "";}
 private void cancelEdit(){detailEpoch++;service.editLease.close();editing=false;editableControls.clear();render();statusLabel.setText("已取消编辑");}
 private void submitEdit(){if(saving||!editing||!service.editLease.valid()){statusLabel.setText(LeaseClient.LOST);return;}long submissionEpoch=detailEpoch;Teacher teacher=overview.getTeacher();Map<String,String> changed=new LinkedHashMap<>();for(Control control:editableControls){String field=String.valueOf(control.getUserData()),old=showInput(read(teacher,field)),now=controlValue(control);if(REQUIRED.contains(field)&&now.isBlank()){statusLabel.setText(title(field)+"不能为空");return;}if(!old.equals(now))changed.put(field,now);}if(changed.isEmpty()){statusLabel.setText("没有检测到修改内容");return;}if(isAdmin()){Teacher updated=gson.fromJson(gson.toJson(teacher),Teacher.class);try{changed.forEach((field,value)->write(updated,field,value));}catch(Exception exception){statusLabel.setText("格式错误: "+exception.getMessage());return;}saving=true;saveButton.setDisable(true);service.update(updated,m->util.Fx.run(()->{if(disposed||submissionEpoch!=detailEpoch)return;saving=false;saveButton.setDisable(!service.editLease.valid());statusLabel.setText(m.getMessage());if(ok(m)){service.editLease.close();editing=false;service.query(updated.getTeacherId(),this::receiveOverview);}}));}else submitChanges(teacher,changed);}
 private void prepareSixColumns(GridPane g){g.setAlignment(Pos.CENTER_LEFT);g.setHgap(12);g.setVgap(9);g.setMaxWidth(Double.MAX_VALUE);if(g.getColumnConstraints().size()==6)return;g.getColumnConstraints().clear();for(int i=0;i<6;i++){ColumnConstraints c=new ColumnConstraints();if(i%2==0){c.setMinWidth(136);c.setPrefWidth(136);c.setMaxWidth(136);c.setHgrow(Priority.NEVER);}else{c.setMinWidth(0);c.setPrefWidth(150);c.setMaxWidth(Double.MAX_VALUE);c.setHgrow(Priority.ALWAYS);}c.setFillWidth(true);g.getColumnConstraints().add(c);}}
